537	    private Xpb98Status mapToShipmentStatus(String statusText) {
538	        return switch (statusText) {
539	            case "배송완료" -> Xpb98Status.DELIVERED;
540	            case "배송출발" -> Xpb98Status.OUT_FOR_DELIVERY;
541	            default -> Xpb98Status.IN_TRANSIT;
542	        };
