 60	        try {
 61	
 62	            if (user == null) {
 63	                throw new Xcz21Exception("사용자 정보가 없습니다.");
 64	            }
 65	            if (productSize == null) {
 66	                throw new Xrf10Exception("상품 사이즈 정보가 없습니다.");
 67	            }
 68	            if (bidPrice <= 0) {
 69	                throw new Xwh31Exception("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
 70	            }
 71	
 72	
