 77	                    .user(user)
 78	                    .totalAmount(bidPrice)
 79	                    .discountAmount(0)
 80	                    .usedPoints(0)
 81	                    .status(Xdg64Status.PENDING_PAYMENT)
 82	                    .build();
 83	
 84	
 85	            order.addOrderItem(orderItem);
 86	
 87	
